<label class="grid gap-1"><span class="font-bold">Jenis kelamin</span><select name="kategori" x-model="kategori" @change="changeCategory" class="rounded border-slate-300"><option value="L">Laki-laki</option><option value="P">Perempuan</option></select></label><label class="grid gap-1"><span class="font-bold">Nomor urut</span><input name="nomor_urut" type="number" min="1" max="999" required value="{{$candidate?->nomor_urut}}" class="rounded border-slate-300"></label>@foreach(['ketua'=>'Ketua','wakil'=>'Wakil'] as $role=>$title)<div class="relative grid gap-1"><span class="font-bold">Kandidat {{$title}}</span><input type="hidden" name="{{$role}}_nis"><input x-model="search.{{$role}}" @focus="open.{{$role}}=true" @input="open.{{$role}}=true" class="rounded border-slate-300" :placeholder="label({{$role}})"><p x-show="{{$role}}" x-text="label(students.find(s=>+s.nis===+{{$role}}))" class="text-sm text-emerald-700"></p><div x-show="open.{{$role}}" x-cloak class="absolute top-full z-20 max-h-52 w-full overflow-auto rounded border bg-white shadow"><p x-show="loading" class="p-3 text-sm">Memuat siswa…</p><template x-for="s in list('{{$role}}')" :key="s.nis"><button type="button" @click="pick('{{$role}}',s)" class="block w-full px-3 py-2 text-left hover:bg-emerald-50" x-text="label(s)"></button></template><p x-show="!loading&&list('{{$role}}').length===0" class="p-3 text-sm">Siswa tidak ditemukan.</p></div></div>@endforeach<label class="grid gap-1"><span class="font-bold">Visi</span><textarea name="visi" class="rounded border-slate-300">{{$candidate?->visi}}</textarea></label><label class="grid gap-1"><span class="font-bold">Misi</span><textarea name="misi" class="rounded border-slate-300">{{$candidate?->misi}}</textarea></label><div class="grid gap-2"><span class="font-bold">Foto Pasangan Kandidat</span><input type="file" accept="image/jpeg,image/png,image/heic,image/heif,.heic,.heif" @change="photo"><p class="text-xs text-slate-500">Maks. 10 MB; browser mengubahnya ke WebP (maks. 1600 px).</p><template x-if="preview"><img :src="preview" class="h-32 rounded object-cover" alt="Preview"></template>@if($candidate?->photoUrl())<img x-show="!preview" src="{{$candidate->photoUrl()}}" class="h-32 rounded object-cover" alt="Foto saat ini">@endif<p x-show="status" x-text="status" class="text-sm"></p><div x-show="uploading" class="h-2 rounded bg-slate-200"><div class="h-full bg-emerald-600" :style="`width:${progress}%`"></div></div></div><p x-show="error" x-text="error" class="text-sm text-red-700 md:col-span-2"></p><button :disabled="loading||uploading" class="rounded bg-emerald-700 px-4 py-2 font-bold text-white disabled:opacity-50 md:col-span-2">{{$button}}</button>
